{"command":"cat <<'EOF' > test_lcs.rs
use std::time::Instant;

fn main() {
    let a: Vec<&str> = (0..5000).map(|_| "A").collect();
    let b: Vec<&str> = (0..5000).map(|_| "B").collect();
    let start = Instant::now();
    let n = a.len();
    let m = b.len();
    let mut dp = vec![vec![0; m + 1]; n + 1];

    for i in 1..=n {
        for j in 1..=m {
            if a[i - 1] == b[j - 1] {
                dp[i][j] = dp[i - 1][j - 1] + 1;
            } else {
                dp[i][j] = std::cmp::max(dp[i - 1][j], dp[i][j - 1]);
            }
        }
    }
    println!("{:?}", start.elapsed());
}
