{"command":"cat <<'EOF' > test_myers.rs
use std::time::Instant;

#[derive(Debug, PartialEq, Clone, Copy)]
enum DiffOp {
    Equal,
    Delete,
    Insert,
}

fn myers_diff<'a>(a: &[&'a str], b: &[&'a str]) -> Vec<(DiffOp, &'a str)> {
    let n = a.len();
    let m = b.len();
    let max = n + m;
    if max == 0 { return vec![]; }

    let mut v = vec![0isize; 2 * max + 1];
    let mut trace = Vec::with_capacity(max + 1);

    for d in 0..=max as isize {
        let mut row = vec![0isize; 2 * d as usize + 1];
        for k in (-d..=d).step_by(2) {
            let idx = (k + max as isize) as usize;

            let mut x = if k == -d || (k != d && v[idx - 1] < v[idx + 1]) {
                v[idx + 1]
            } else {
                v[idx - 1] + 1
            };

            let mut y = x - k;

            while x >= 0 && y >= 0 && (x as usize) < n && (y as usize) < m && a[x as usize] == b[y as usize] {
                x += 1;
                y += 1;
            }
            v[idx] = x;
            row[(k + d) as usize] = x;

            if x as usize >= n && y as usize >= m {
                let mut ops = Vec::new();
                let mut x = n as isize;
                let mut y = m as isize;

                for step in (0..d).rev() {
                    let row_trace = &trace[step as usize];
                    let k = x - y;

                    let prev_k = if k == -(step + 1) || (k != step + 1 && row_trace[(k - 1 + step) as usize] < row_trace[(k + 1 + step) as usize]) {
                        k + 1
                    } else {
                        k - 1
                    };

                    let prev_x = row_trace[(prev_k + step) as usize];
                    let prev_y = prev_x - prev_k;

                    while x > prev_x && y > prev_y && x > 0 && y > 0 && a[x as usize - 1] == b[y as usize - 1] {
                        x -= 1;
                        y -= 1;
                        ops.push((DiffOp::Equal, a[x as usize]));
                    }
                    if x == prev_x {
                        y -= 1;
                        ops.push((DiffOp::Insert, b[y as usize]));
                    } else {
                        x -= 1;
                        ops.push((DiffOp::Delete, a[x as usize]));
                    }
                }
                while x > 0 && y > 0 && a[x as usize - 1] == b[y as usize - 1] {
                    x -= 1;
                    y -= 1;
                    ops.push((DiffOp::Equal, a[x as usize]));
                }
                ops.reverse();
                return ops;
            }
        }
        trace.push(row);
    }
    vec![]
}

fn main() {
    let a = vec!["A", "B", "C", "A", "B", "B", "A"];
    let b = vec!["C", "B", "A", "B", "A", "C"];
    let ops = myers_diff(&a, &b);
    for op in ops {
        println!("{:?}", op);
    }
}
EOF
