#[derive(Clone, Default)]
struct Style {
    fg: Option<Color>,
    bg: Option<Color>,
    bold: bool,
    italic: bool,
    underline: bool,
    intense: bool,
}

#[derive(Clone)]
enum Color {
    Ansi(u8),
    Xterm(u8),
    TrueColor(u8, u8, u8),
}

fn to_ansi(style: &Style) -> String {
    let mut parts = Vec::new();
    if style.bold { parts.push("1".to_string()); }
    if style.italic { parts.push("3".to_string()); }
    if style.underline { parts.push("4".to_string()); }

    if let Some(fg) = &style.fg {
        match fg {
            Color::Ansi(c) => if style.intense { parts.push(format!("38;5;{}", c+8)); } else { parts.push(format!("3{}", c)); },
            Color::Xterm(c) => parts.push(format!("38;5;{}", c)),
            Color::TrueColor(r,g,b) => parts.push(format!("38;2;{};{};{}", r,g,b)),
        }
    }
    if let Some(bg) = &style.bg {
        match bg {
            Color::Ansi(c) => if style.intense { parts.push(format!("48;5;{}", c+8)); } else { parts.push(format!("4{}", c)); },
            Color::Xterm(c) => parts.push(format!("48;5;{}", c)),
            Color::TrueColor(r,g,b) => parts.push(format!("48;2;{};{};{}", r,g,b)),
        }
    }
    if parts.is_empty() {
        return "".to_string();
    }
    format!("\x1b[{}m", parts.join(";"))
}

#[derive(PartialEq)]
enum LineNumbers {
    Off,
    Compact,
    Aligned,
}

struct App {
    add: Style,
    rem: Style,
    ref_add: Style,
    ref_rem: Style,
    line_nums: LineNumbers,

    cur_rem: usize,
    cur_add: usize,
    max_rem: usize,
    max_add: usize,
}

impl App {
    fn new() -> Self {
        let mut app = App {
            add: Style::default(),
            rem: Style::default(),
            ref_add: Style::default(),
            ref_rem: Style::default(),
            line_nums: LineNumbers::Off,
            cur_rem: 0,
            cur_add: 0,
            max_rem: 0,
            max_add: 0,
        };
        app.add.fg = Some(Color::Ansi(2)); // green
        app.rem.fg = Some(Color::Ansi(1)); // red

        app.ref_add.fg = Some(Color::TrueColor(255,255,255));
        app.ref_add.bg = Some(Color::Ansi(2));
        app.ref_add.bold = true;

        app.ref_rem.fg = Some(Color::TrueColor(255,255,255));
        app.ref_rem.bg = Some(Color::Ansi(1));
        app.ref_rem.bold = true;

        app
    }

    fn parse_colors(&mut self, spec: &str) {
        let parts: Vec<&str> = spec.split(':').collect();
        if parts.is_empty() { return; }
        let face = parts[0];

        let style = match face {
            "added" => &mut self.add,
            "removed" => &mut self.rem,
            "refine-added" => &mut self.ref_add,
            "refine-removed" => &mut self.ref_rem,
            _ => return,
        };

        let mut i = 1;
        while i < parts.len() {
            let attr = parts[i];
            match attr {
                "none" => {
                    *style = Style::default();
                },
                "bold" => style.bold = true,
                "nobold" => style.bold = false,
                "italic" => style.italic = true,
                "noitalic" => style.italic = false,
                "underline" => style.underline = true,
                "nounderline" => style.underline = false,
                "intense" => style.intense = true,
                "nointense" => style.intense = false,
                "foreground" | "background" if i + 1 < parts.len() => {
                    let color_str = parts[i + 1];
                    i += 1;

                    let parsed_color = if color_str == "none" {
                        None
                    } else if color_str == "black" { Some(Color::Ansi(0)) }
                    else if color_str == "red" { Some(Color::Ansi(1)) }
                    else if color_str == "green" { Some(Color::Ansi(2)) }
                    else if color_str == "yellow" { Some(Color::Ansi(3)) }
                    else if color_str == "blue" { Some(Color::Ansi(4)) }
                    else if color_str == "magenta" { Some(Color::Ansi(5)) }
                    else if color_str == "cyan" { Some(Color::Ansi(6)) }
                    else if color_str == "white" { Some(Color::TrueColor(255,255,255)) }
                    else if let Ok(val) = color_str.parse::<u8>() {
                        Some(Color::Xterm(val))
                    } else {
                        let c_parts: Vec<&str> = color_str.split(',').collect();
                        if c_parts.len() == 3 {
                            if let (Ok(r), Ok(g), Ok(b)) = (c_parts[0].parse(), c_parts[1].parse(), c_parts[2].parse()) {
                                Some(Color::TrueColor(r, g, b))
                            } else { None }
                        } else { None }
                    };
                    if attr == "foreground" {
                        style.fg = parsed_color;
                    } else {
                        style.bg = parsed_color;
                    }
                }
                _ => {}
            }
            i += 1;
        }
    }
}
