fn split_prefix(s: &str) -> (&str, &str) {
    if s.is_empty() { return ("", ""); }
    let chars: Vec<char> = s.chars().collect();
    let mut i = 0;
    if chars[i] == '-' || chars[i] == '+' || chars[i] == ' ' {
        i += 1;
        while i < chars.len() && (chars[i] == ' ' || chars[i] == '\t') {
            i += 1;
        }
    }
    let p_len = chars[..i].iter().map(|c| c.len_utf8()).sum();
    (&s[..p_len], &s[p_len..])
}

fn process_block(rem: &[String], add: &[String], app: &mut App) {
    if rem.is_empty() && add.is_empty() { return; }

    let mut rem_texts = Vec::new();
    let mut rem_prefixes = Vec::new();
