use std::env;
use std::io::{self, BufRead, Write};

#[derive(Debug, PartialEq, Clone, Copy)]
enum DiffOp {
    Equal,
    Delete,
    Insert,
}

fn myers_diff<'a>(a: &[&'a str], b: &[&'a str]) -> Vec<(DiffOp, &'a str)> {
    let n = a.len();
    let m = b.len();
    let max = n + m;
    if max == 0 { return vec![]; }

    let mut v = vec![0isize; 2 * max + 1];
    let mut trace: Vec<Vec<isize>> = Vec::with_capacity(max + 1);

    let mut x = 0;
    while x < n && x < m && a[x] == b[x] {
        x += 1;
    }
    v[max] = x as isize;
    if x == n && x == m {
        return a.iter().map(|&s| (DiffOp::Equal, s)).collect();
    }

    for d in 0..=max as isize {
        let mut row = vec![0isize; 2 * d as usize + 1];
        for k in (-d..=d).step_by(2) {
            let idx = (k + max as isize) as usize;

            let mut x = if d == 0 {
                0
            } else if k == -d || (k != d && v[idx - 1] < v[idx + 1]) {
                v[idx + 1]
            } else {
                v[idx - 1] + 1
            };

            let mut y = x - k;

            while x >= 0 && y >= 0 && (x as usize) < n && (y as usize) < m && a[x as usize] == b[y as usize] {
                x += 1;
                y += 1;
            }
            v[idx] = x;
            row[(k + d) as usize] = x;

            if x as usize >= n && y as usize >= m {
                trace.push(row);
                let mut ops = Vec::new();
                let mut x = n as isize;
                let mut y = m as isize;

                for step in (1..=d).rev() {
                    let row_trace = &trace[(step - 1) as usize];
                    let k = x - y;

                    let prev_k = if k == -step || (k != step && row_trace[(k - 1 + step - 1) as usize] < row_trace[(k + 1 + step - 1) as usize]) {
                        k + 1
                    } else {
                        k - 1
                    };

                    let prev_x = row_trace[(prev_k + step - 1) as usize];
                    let prev_y = prev_x - prev_k;

                    while x > prev_x && y > prev_y && x > 0 && y > 0 && a[x as usize - 1] == b[y as usize - 1] {
                        x -= 1;
                        y -= 1;
                        ops.push((DiffOp::Equal, a[x as usize]));
                    }
