fn split_prefix(s: &str) -> (&str, &str) {
    if s.is_empty() { return ("", ""); }
    let chars: Vec<char> = s.chars().collect();
    let mut i = 0;
    if chars[i] == '-' || chars[i] == '+' || chars[i] == ' ' {
        i += 1;
        while i < chars.len() && (chars[i] == ' ' || chars[i] == '\t') {
            i += 1;
        }
    }
    let p_len = chars[..i].iter().map(|c| c.len_utf8()).sum();
    (&s[..p_len], &s[p_len..])
}

fn print_line_num(is_rem: bool, is_add: bool, rem_line: usize, add_line: usize, n: usize, mode: &LineNumbers, color: &str) {
    if mode == &LineNumbers::Off { return; }
    let rem_str = if is_rem { format!("{}", rem_line) } else { "".to_string() };
    let add_str = if is_add { format!("{}", add_line) } else { "".to_string() };

    let s = format!("{:>width$} {:>width$}", rem_str, add_str, width = n);
    if color.is_empty() {
        if mode == &LineNumbers::Compact {
            print!("{}\x1b[0m", s);
        } else {
            print!("{}\t\x1b[0m", s);
        }
    } else {
        if mode == &LineNumbers::Compact {
            print!("\x1b[0m{}{}\x1b[0m", color, s);
        } else {
            print!("\x1b[0m{}{}\x1b[0m\t", color, s);
        }
    }
}
