struct DiffBlock {
    rem: Vec<String>,
    rem_meta: Vec<String>,
    add: Vec<String>,
    add_meta: Vec<String>,
}

impl DiffBlock {
    fn new() -> Self {
        DiffBlock {
            rem: Vec::new(),
            rem_meta: Vec::new(),
            add: Vec::new(),
            add_meta: Vec::new(),
        }
    }

    fn is_empty(&self) -> bool {
        self.rem.is_empty() && self.add.is_empty()
    }
}

fn process_block(block: &DiffBlock, app: &mut App) {
    if block.is_empty() { return; }

    let mut rem_texts = Vec::new();
    let mut rem_prefixes = Vec::new();
    for l in &block.rem {
        let (p, t) = split_prefix(l);
        rem_prefixes.push(p.to_string());
        rem_texts.push(t.to_string());
    }

    let mut add_texts = Vec::new();
    let mut add_prefixes = Vec::new();
    for l in &block.add {
        let (p, t) = split_prefix(l);
        add_prefixes.push(p.to_string());
        add_texts.push(t.to_string());
    }

    let mut joined_rem = rem_texts.join("\n");
    if !joined_rem.is_empty() || !block.rem.is_empty() {
        joined_rem.push('\n');
    }

    let mut joined_add = add_texts.join("\n");
    if !joined_add.is_empty() || !block.add.is_empty() {
        joined_add.push('\n');
    }

    let tok_rem = tokenize(&joined_rem);
    let tok_add = tokenize(&joined_add);

    let ops = myers_diff(&tok_rem, &tok_add);

    let n = format!("{}", std::cmp::max(app.max_rem, app.max_add)).len();

    let rem_col = to_ansi(&app.rem);
    let ref_rem_col = to_ansi(&app.ref_rem);
    let add_col = to_ansi(&app.add);
    let ref_add_col = to_ansi(&app.ref_add);

    if !block.rem.is_empty() {
        let mut line_idx = 0;
        print_line_num(true, false, app.cur_rem, 0, n, &app.line_nums, &rem_col);
        print!("\x1b[0m{}{}\x1b[0m", rem_col, rem_prefixes[0]);
        app.cur_rem += 1;

        let mut current = String::new();

        for op in &ops {
            match op {
                (DiffOp::Equal, t) => {
                    let style = &rem_col;
                    for c in t.chars() {
                        if c == '\n' {
                            print!("\x1b[0m{}{}\x1b[0m\n", style, current);
                            current.clear();
                            line_idx += 1;
                            if line_idx < rem_prefixes.len() {
                                print_line_num(true, false, app.cur_rem, 0, n, &app.line_nums, &rem_col);
                                print!("\x1b[0m{}{}\x1b[0m", rem_col, rem_prefixes[line_idx]);
                                app.cur_rem += 1;
                            }
                        } else {
                            current.push(c);
                        }
                    }
                    if !current.is_empty() {
                        print!("\x1b[0m{}{}\x1b[0m", style, current);
                        current.clear();
                    }
                },
                (DiffOp::Delete, t) => {
                    let style = &ref_rem_col;
                    for c in t.chars() {
                        if c == '\n' {
                            print!("\x1b[0m{}{}\x1b[0m\n", style, current);
                            current.clear();
                            line_idx += 1;
                            if line_idx < rem_prefixes.len() {
                                print_line_num(true, false, app.cur_rem, 0, n, &app.line_nums, &rem_col);
                                print!("\x1b[0m{}{}\x1b[0m", rem_col, rem_prefixes[line_idx]);
