                    }
                },
                (DiffOp::Insert, t) => {
                    let style = &ref_add_col;
                    for c in t.chars() {
                        if c == '\n' {
                            print!("\x1b[0m{}{}\x1b[0m\n", style, current);
                            current.clear();
