fn main() {
    let args: Vec<String> = env::args().collect();
    let mut app = App::new();

    let mut i = 1;
    while i < args.len() {
        if args[i] == "--colors" && i + 1 < args.len() {
            app.parse_colors(&args[i + 1]);
            i += 2;
        } else if args[i] == "--line-numbers" {
            if i + 1 < args.len() && !args[i + 1].starts_with('-') {
                if args[i + 1] == "aligned" {
                    app.line_nums = LineNumbers::Aligned;
                } else {
                    app.line_nums = LineNumbers::Compact;
                }
                i += 2;
            } else {
                app.line_nums = LineNumbers::Compact;
                i += 1;
            }
        } else {
            i += 1;
        }
    }

    let stdin = io::stdin();
    let mut block = DiffBlock::new();
    let mut is_adding = false; // true if we just saw '+' lines and might see `\ No newline...`

    for line in stdin.lock().lines() {
        if let Ok(l) = line {
            if l.starts_with("---") || l.starts_with("+++") || l.starts_with("@@") {
                process_block(&block, &mut app);
                block = DiffBlock::new();

                if l.starts_with("@@") {
                    let parts: Vec<&str> = l.split_whitespace().collect();
                    if parts.len() >= 3 {
                        let rem_part = parts[1].trim_start_matches('-');
                        let add_part = parts[2].trim_start_matches('+');
                        let r_start = rem_part.split(',').next().unwrap_or("0").parse().unwrap_or(0);
                        let a_start = add_part.split(',').next().unwrap_or("0").parse().unwrap_or(0);
                        let r_len = rem_part.split(',').nth(1).unwrap_or("1").parse().unwrap_or(1);
                        let a_len = add_part.split(',').nth(1).unwrap_or("1").parse().unwrap_or(1);
                        app.cur_rem = r_start;
                        app.cur_add = a_start;
                        app.max_rem = if r_len > 0 { r_start + r_len - 1 } else { r_start };
                        app.max_add = if a_len > 0 { a_start + a_len - 1 } else { a_start };
                    }
                }

                print!("\x1b[0m{}\x1b[0m\n", l);
                is_adding = false;
            } else if l.starts_with('-') {
                block.rem.push(l);
                is_adding = false;
            } else if l.starts_with('+') {
                block.add.push(l);
                is_adding = true;
            } else if l.starts_with('\\') {
                if is_adding {
                    block.add_meta.push(l);
                } else if !block.rem.is_empty() {
                    block.rem_meta.push(l);
                } else {
                    process_block(&block, &mut app);
                    block = DiffBlock::new();
                    print!("\x1b[0m{}\x1b[0m\n", l);
                }
            } else if l.starts_with(' ') {
                process_block(&block, &mut app);
                block = DiffBlock::new();

                let n = format!("{}", std::cmp::max(app.max_rem, app.max_add)).len();
                print_line_num(false, true, app.cur_rem, app.cur_add, n, &app.line_nums, "");
                print!("{}\x1b[0m\n", l);

                app.cur_rem += 1;
                app.cur_add += 1;
                is_adding = false;
            } else {
                process_block(&block, &mut app);
                block = DiffBlock::new();
                print!("\x1b[0m{}\x1b[0m\n", l);
                is_adding = false;
            }
        }
    }
    process_block(&block, &mut app);
}
