struct App { add: Style, rem: Style, ref_add: Style, ref_rem: Style, line_nums: LineNumbers, cur_rem: usize, cur_add: usize, max_rem: usize, max_add: usize }

impl App {
    fn new() -> Self {
        let mut app = App { add: Style::default(), rem: Style::default(), ref_add: Style::default(), ref_rem: Style::default(), line_nums: LineNumbers::Off, cur_rem: 0, cur_add: 0, max_rem: 0, max_add: 0 };
        app.add.fg = Some(Color::Ansi(2)); app.rem.fg = Some(Color::Ansi(1));
        app.ref_add.fg = Some(Color::TrueColor(255,255,255)); app.ref_add.bg = Some(Color::Ansi(2)); app.ref_add.bold = true;
        app.ref_rem.fg = Some(Color::TrueColor(255,255,255)); app.ref_rem.bg = Some(Color::Ansi(1)); app.ref_rem.bold = true;
