    }

    fn parse_colors(&mut self, spec: &str) {
        let parts: Vec<&str> = spec.split(':').collect();
        if parts.is_empty() { return; }
        let face = parts[0];
        let style = match face { "added" => &mut self.add, "removed" => &mut self.rem, "refine-added" => &mut self.ref_add, "refine-removed" => &mut self.ref_rem, _ => return };
        let mut i = 1;
        while i < parts.len() {
            let attr = parts[i];
            match attr {
                "none" => *style = Style::default(),
                "bold" => style.bold = true, "nobold" => style.bold = false,
                "italic" => style.italic = true, "noitalic" => style.italic = false,
                "underline" => style.underline = true, "nounderline" => style.underline = false,
                "intense" => style.intense = true, "nointense" => style.intense = false,
                "foreground" | "background" if i + 1 < parts.len() => {
                    let c_str = parts[i + 1]; i += 1;
                    let parsed = if c_str == "none" { None } else if c_str == "black" { Some(Color::Ansi(0)) } else if c_str == "red" { Some(Color::Ansi(1)) } else if c_str == "green" { Some(Color::Ansi(2)) } else if c_str == "yellow" { Some(Color::Ansi(3)) } else if c_str == "blue" { Some(Color::Ansi(4)) } else if c_str == "magenta" { Some(Color::Ansi(5)) } else if c_str == "cyan" { Some(Color::Ansi(6)) } else if c_str == "white" { Some(Color::Ansi(7)) } else if let Ok(v) = c_str.parse() { Some(Color::Xterm(v)) } else { let cp: Vec<&str> = c_str.split(',').collect(); if cp.len() == 3 { if let (Ok(r), Ok(g), Ok(b)) = (cp[0].parse(), cp[1].parse(), cp[2].parse()) { Some(Color::TrueColor(r, g, b)) } else { None } } else { None } };
