#[derive(Debug, PartialEq, Clone, Copy)]
enum DiffOp { Equal, Delete, Insert }

fn myers_diff<'a>(a: &[&'a str], b: &[&'a str]) -> Vec<(DiffOp, &'a str)> {
    let n = a.len(); let m = b.len(); let max = n + m;
    if max == 0 { return vec![]; }
