fn is_word_char(c: char) -> bool { c.is_alphanumeric() || c == '_' }
fn is_space_char(c: char) -> bool { c.is_whitespace() && c != '\\n' }

fn tokenize(s: &str) -> Vec<&str> {
    let mut tokens = Vec::new();
    let mut chars = s.char_indices().peekable();
    while let Some((i, c)) = chars.next() {
        if c == '\\n' { tokens.push(&s[i..i + c.len_utf8()]); }
        else if is_space_char(c) {
            let start = i; let mut end = i + c.len_utf8();
            while let Some(&(j, next_c)) = chars.peek() {
                if is_space_char(next_c) { end = j + next_c.len_utf8(); chars.next(); } else { break; }
            }
            tokens.push(&s[start..end]);
        } else if is_word_char(c) {
            let start = i; let mut end = i + c.len_utf8();
            while let Some(&(j, next_c)) = chars.peek() {
                if is_word_char(next_c) { end = j + next_c.len_utf8(); chars.next(); } else { break; }
            }
            tokens.push(&s[start..end]);
        } else { tokens.push(&s[i..i + c.len_utf8()]); }
    }
    tokens
}

